import { icon, artwork } from './icons.js';
import { DEMO_USER, PEOPLE, SPOTS, demoPosts } from './data.js';
import { api, configured } from './api.js';
import { escapeHtml as e, initials, dateLabel, timeLabel, relative, filterPosts, validatePost, makeICS, readLocal, saveLocal, TYPES, CATEGORIES } from './core.js';
const $ = s => document.querySelector(s);
const demo = readLocal('fhv-demo-v1',null);
const state = {mode:'demo',user:demo?.user || {...DEMO_USER},posts:demo?.posts || demoPosts(),joined:demo?.joined || ['hike'],saved:demo?.saved || [],liked:demo?.liked || [],comments:demo?.comments || {},chats:demo?.chats || [],messages:demo?.messages || {},invitations:demo?.invitations || [{id:'invite-coffee',post_id:'coffee',sender_id:'demo-oh',status:'pending'},{id:'invite-run',post_id:'run',sender_id:'demo-lena',status:'pending'}],tab:['feed','trade','activities','profile'].includes(location.hash.slice(1))?location.hash.slice(1):'feed',filter:'Alle',query:'',activityTab:'Entdecken',tradeTab:'Angebote',overlay:null,selected:null,busy:false,loading:false,authMode:'login',createType:'activity',createCategory:'Campus',currentChat:null,noticeRead:false};
let deferredInstall, chatInterval, lastFocus;
const fhvMark = `<svg viewBox="0 0 460 460" fill="currentColor" aria-hidden="true"><path d="M10.8 346.8h337.5V234.3H10.8V121.7h337.6V9.1H461v450.2H10.9l-.1-112.5z"/></svg>`;
const logo = `<span class="wordmark" role="img" aria-label="FHV Friends"><span class="logo-eyebrow">FHV</span><span class="logo-name">${fhvMark}<span>riends<span class="logo-dot">.</span></span></span></span>`;
const avatar = (person,size='') => `<span class="avatar ${person?.color||'blue'} ${size}" aria-hidden="true">${person?.role==='oh'?'ÖH':e(initials(person?.name))}</span>`;
const isOh = () => ['oh','admin'].includes(state.user?.role);
const isDemo = () => state.mode==='demo';
const joined = id => state.joined.includes(id);
const count = p => p.join_count || 0;
const full = p => p.capacity && count(p)>=p.capacity && !joined(p.id);
const pendingInvites = () => state.invitations.filter(i=>i.status==='pending');
function persist() { if(isDemo()) saveLocal('fhv-demo-v1',{user:state.user,posts:state.posts,joined:state.joined,saved:state.saved,liked:state.liked,comments:state.comments,chats:state.chats,messages:state.messages,invitations:state.invitations}); }
function toast(message) { $('#toast').textContent=message; $('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),3500); }
function empty(title,description,action='create',button='Etwas starten') { return `<div class="empty-state"><span class="empty-icon">${icon('spark',32)}</span><h3>${title}</h3><p>${description}</p>${action?`<button class="btn primary" data-action="${action}">${button}</button>`:''}</div>`; }
function nav() { return `<nav class="bottom-nav" aria-label="Hauptnavigation">${[['feed','home','Home / Feed'],['trade','trade','Trade / Help'],['create','plus','Erstellen'],['activities','calendar','Activities'],['profile','user','Profile']].map(([id,ico,label])=>`<button class="nav-item ${id==='create'?'nav-create':''} ${state.tab===id?'active':''}" ${state.tab===id?'aria-current="page"':''} data-action="${id==='create'?'create':'nav'}" data-tab="${id}" aria-label="${label}"><span class="nav-icon">${icon(ico,id==='create'?29:23)}</span><span class="nav-label">${label}</span></button>`).join('')}</nav>`; }
function sidebar() { return `<aside class="sidebar"><button class="brand" data-action="nav" data-tab="feed" aria-label="FHV Friends Startseite">${logo}</button><span class="campus-label">DORNBIRN, DEIN CAMPUS</span><nav aria-label="Desktop-Navigation">${[['feed','home','Dein Feed'],['trade','trade','Trade / Help'],['activities','calendar','Activities'],['profile','user','Dein Profil']].map(([id,ico,label])=>`<button class="side-link ${state.tab===id?'active':''}" ${state.tab===id?'aria-current="page"':''} data-action="nav" data-tab="${id}">${icon(ico)}<span>${label}</span>${id==='activities'?'<span class="new-dot"></span>':''}</button>`).join('')}<button class="side-link" data-action="inbox">${icon('chat')}<span>Nachrichten</span></button></nav><button class="btn primary side-create" data-action="create">${icon('plus',20)} Etwas starten</button><div class="sidebar-bottom"><div class="campus-note"><span class="tiny-label">DIE BESTEN PLÄNE?</span><p>Fangen mit einem<br><em>„Bist du dabei?“</em> an.</p><span class="note-doodle">${icon('spark',38)}</span></div><button class="side-user" data-action="${isDemo()?'auth':'nav'}" data-tab="profile">${avatar(state.user)}<span><strong>${e(state.user.name)}</strong><small>${isDemo()?'Demo erkunden':'FHV Community'}</small></span>${icon(isDemo()?'logout':'chevron',18)}</button><div class="sidebar-foot"><button data-action="about">Über FHV Friends</button><span>Von Studierenden. Für uns.</span></div></div></aside>`; }
function header() { const titles={feed:['Hey, Campus.','Deine Leute sind schon da.'],trade:['Geben. Nehmen. Helfen.','Was du nicht mehr brauchst, macht andere glücklich.'],activities:['Raus aus dem Alltag.','Gute Pläne. Noch bessere Gesellschaft.'],profile:['Ein bisschen du.','Der Anfang einer guten Verbindung.']}; const [title,sub]=titles[state.tab] || titles.feed; return `<header class="page-header"><div class="mobile-brand">${logo}</div><div class="eyebrow">${icon('map',13)} FHV · DORNBIRN <span class="header-date">${dateLabel(new Date(),{weekday:'long'})}</span></div><div class="header-main"><div><h1>${title}</h1><p>${sub}</p></div><div class="header-actions"><button class="icon-btn" data-action="inbox" aria-label="Nachrichten öffnen">${icon('chat')}</button><button class="icon-btn notification-btn" data-action="notifications" aria-label="Einladungen und Neuigkeiten">${icon('bell')}${!state.noticeRead&&pendingInvites().length?'<span class="notification-dot"></span>':''}</button></div></div></header>`; }
function statusBanner() { return `<div class="status-bar ${isDemo()?'demo-bar':'live-bar'}"><span>${icon(isDemo()?'sun':'shield',15)}${isDemo()?'<strong>Ein Blick in deinen Campus.</strong> <span class="demo-extra">Demo mit Beispieldaten · nur auf diesem Gerät.</span>':'Nur für die FHV Community. Schön, dass du da bist.'}</span>${isDemo()?'<button data-action="auth">Anmelden '+icon('chevron',14)+'</button>':''}</div>`; }
function chips(items,selected,action='filter') { return `<div class="chips" role="group" aria-label="Filtern">${items.map(f=>`<button class="chip ${selected===f?'selected':''}" aria-pressed="${selected===f}" data-action="${action}" data-value="${f}">${f}</button>`).join('')}</div>`; }
function searchBox(placeholder='Wonach suchst du?') { return `<label class="search-box">${icon('search',20)}<input id="search" type="search" value="${e(state.query)}" placeholder="${placeholder}" aria-label="${placeholder}" autocomplete="off"><kbd>/</kbd></label>`; }
function authorLine(p) { return `<div class="author-line">${avatar(p.author)}<div><strong>${e(p.author?.name || 'Campus-Mitglied')}${p.pinned||p.author?.role==='oh'?'<span class="verified" title="Verifizierte ÖH">'+icon('check',11)+'</span>':''}</strong><small>${e(p.author?.course || 'FHV Community')} · ${relative(p.created_at)}</small></div><button class="icon-btn small card-more" data-action="post-menu" data-id="${p.id}" aria-label="Beitragsoptionen">${icon('more',20)}</button></div>`; }
function bookmarkButton(p) { const saved=state.saved.includes(p.id);return `<button class="icon-btn small ${saved?'is-saved':''}" data-action="save" data-id="${p.id}" aria-label="${saved?'Nicht mehr merken':'Beitrag merken'}" aria-pressed="${saved}">${icon('bookmark',19)}</button>`; }
function hero(p) { return `<article class="hero-card"><div class="hero-copy"><div class="hero-top"><span class="pinned-label">${icon('pin',14)} VON ÖH FHV ANGEPINNT</span><span class="official-badge">${icon('check',12)} Official</span></div><span class="hero-overline">EINE OFFENE EINLADUNG</span><h2>${e(p.title)}</h2><p>Kaffee, Brettspiele & vielleicht<br>deine nächsten Lieblingsmenschen.</p><div class="hero-meta">${icon('calendar',15)} ${dateLabel(p.starts_at,{weekday:'short'})} · ${timeLabel(p.starts_at)} <span>·</span> Café Campus</div><div class="hero-bottom"><div class="going-stack">${miniAvatars()}<span><strong>${count(p)}</strong> sind dabei</span></div><button class="btn blue" data-action="detail" data-id="${p.id}">${joined(p.id)?icon('check',17)+' Du bist dabei':'Bin dabei'} ${!joined(p.id)?icon('plus',17):''}</button></div></div><div class="hero-art">${artwork('coffee')}<span class="floating-tag">Komm allein.<br>Geh mit neuen Freunden.</span><span class="date-tile"><small>${dateLabel(p.starts_at,{month:'short'}).replace(/\d+\.?\s*/,'').toUpperCase()}</small><strong>${new Date(p.starts_at).getDate()}</strong></span></div></article>`; }
function miniAvatars() { return `<span class="mini-avatars">${[PEOPLE.lena,PEOPLE.felix,PEOPLE.sarah].map(p=>avatar(p,'mini')).join('')}</span>`; }
function postCard(p,{compact=false}={}) { const activity=p.type==='activity'; const tone={activity:'blue',food:'green',trade:'lavender',help:'yellow',life:'coral'}[p.type];const liked=state.liked.includes(p.id); return `<article class="post-card ${compact?'compact':''}">${authorLine(p)}${p.art?`<button class="card-visual" data-action="detail" data-id="${p.id}" aria-label="${e(p.title)} ansehen">${artwork(p.art)}<span class="visual-badge">${activity?e(p.category):p.type==='trade'?(p.price?`${p.price} €`:'Für 0 €. Für dich.'):p.type==='food'?'Zu gut zum Wegwerfen':p.type==='help'?'Zusammen geht’s leichter':''}</span>${activity?`<span class="mini-date"><strong>${new Date(p.starts_at).getDate()}</strong><span>${dateLabel(p.starts_at,{month:'short'}).replace(/\d+\.?\s*/,'')}</span></span>`:''}</button>`:''}<div class="card-body"><div class="card-kicker"><span class="type-label ${tone}">${e(TYPES[p.type])}</span>${p.type==='help'?`<span class="secondary-label">${p.help_direction==='request'?'Sucht Hilfe':'Bietet Hilfe'}</span>`:''}${p.status==='reserved'?'<span class="reserved-label">Reserviert</span>':''}</div><button class="text-link card-title" data-action="detail" data-id="${p.id}"><h3>${e(p.title)}</h3></button><p class="card-description">${e(p.description)}</p><div class="card-meta">${icon(activity?'calendar':'map',14)} ${activity?`${dateLabel(p.starts_at,{weekday:'short'})} · ${timeLabel(p.starts_at)}`:e(p.location)}</div><div class="card-footer"><button class="like-btn ${liked?'liked':''}" aria-label="Gefällt mir" aria-pressed="${liked}" data-action="like" data-id="${p.id}">${icon('heart',18)}<span>${Number(p.likes||0)}</span></button>${activity?`<span class="going-label">${icon('people',15)} ${count(p)} dabei</span>`:`<span class="price-label">${p.price?`${p.price} €`:'Kostenlos'}</span>`}<div class="card-footer-right">${bookmarkButton(p)}<button class="btn small ${joined(p.id)?'joined':'soft'}" data-action="detail" data-id="${p.id}">${activity?(joined(p.id)?icon('check',14)+' Dabei':full(p)?'Ausgebucht':'Mitmachen'):p.type==='help'?'Kontakt':'Ansehen'}</button></div></div></div></article>`; }
function feed() { const all = filterPosts(state.posts,{tab:'feed',filter:state.filter,query:state.query}); const featured = state.filter==='Alle'&&!state.query?all.find(p=>p.pinned&&p.type==='activity'):null; const rest=all.filter(p=>p.id!==featured?.id); return `${searchBox('Aktivitäten, Dinge oder Hilfe finden …')}${chips(['Alle','Aktivitäten','Verschenken','Essen','Hilfe','Campusleben'],state.filter)}<div id="feed-results">${featured?hero(featured):''}<div class="section-heading"><h2>${state.query?'Deine Suchergebnisse':state.filter==='Alle'?'Gerade auf dem Campus':state.filter}</h2><span>${rest.length} Beiträge ${icon('sun',16)}</span></div><div class="post-grid">${rest.length?rest.map(p=>postCard(p)).join(''):empty('Hier ist noch Platz für dich.','Starte einen Plan oder probiere einen anderen Suchbegriff.')}</div></div>`; }
function trade() { const posts=filterPosts(state.posts,{tab:'trade',filter:state.filter,query:state.query});return `<div class="segment-control">${['Angebote','Campus-Spots'].map(s=>`<button class="${state.tradeTab===s?'selected':''}" data-action="trade-tab" data-value="${s}">${s}</button>`).join('')}</div>${state.tradeTab==='Campus-Spots'?`<div class="spots-intro blue"><span class="tiny-label">TREFFPUNKTE AUF DEM CAMPUS</span><h2>Ein guter Ort,<br>um etwas weiterzugeben.</h2><p>Verabredet euch vorab. Kleine Gesten, große Wirkung.</p>${icon('map',64)}</div><div class="spot-list">${SPOTS.map(s=>`<article class="spot-card"><span class="spot-icon ${s.tone}">${icon(s.icon,27)}</span><div><span class="tiny-label">${s.type}</span><h3>${s.name}</h3><p>${s.description}</p></div></article>`).join('')}</div><div class="info-box">${icon('leaf',23)}<div><strong>Essen teilen? Immer persönlich.</strong><p>Bitte keine verderblichen Lebensmittel unbeaufsichtigt abstellen. Zutaten und Allergene angeben.</p></div></div>`:`${searchBox('Lampe, Lernhilfe oder Mittagessen …')}${chips(['Alle','Verschenken','Essen','Hilfe'],state.filter)}<div class="trade-banner"><div><span class="tiny-label">WENIGER NEU. MEHR MITEINANDER.</span><h2>Deins, meins.<br>Unser Campus.</h2><p>Weitergeben fühlt sich gut an.</p></div><span class="trade-symbol">${icon('trade',72)}</span></div><div class="section-heading"><h2>${state.filter==='Alle'?'Von uns. Für uns.':state.filter}</h2><button class="text-link" data-action="create">${icon('plus',16)} Anbieten</button></div><div class="post-grid">${posts.length?posts.map(p=>postCard(p)).join(''):empty('Gesucht. Noch nicht gefunden.','Frag auf dem Campus oder gib selbst etwas weiter.')}</div>`}`; }
function invitationCard(inv) { const p=state.posts.find(x=>x.id===inv.post_id);if(!p)return '';const who=p.author?.name||'Campus'; return `<article class="invitation-card ${inv.sender_id==='demo-oh'||p.pinned?'yellow':'lavender'}"><span class="tiny-label">${e(who)} ${p.pinned?'· OFFICIAL':'HAT DICH EINGELADEN'}</span><h3>${e(p.subtitle||p.title)}</h3><p>${dateLabel(p.starts_at,{weekday:'short'})} · ${timeLabel(p.starts_at)}</p><small>${e(p.location)} · ${count(p)} dabei</small><div class="invitation-actions"><button class="btn primary" data-action="accept" data-id="${inv.id}">${icon('check',16)} Einladung annehmen</button><button class="btn translucent" data-action="decline" data-id="${inv.id}">Nicht jetzt</button></div></article>`; }
function activities() { const invites=pendingInvites();const posts=filterPosts(state.posts,{tab:'activities',filter:state.filter,query:state.query,activityTab:state.activityTab,userId:state.user.id,joined:state.joined});return `<div class="segment-control activity-segments">${['Entdecken','Einladungen','Meine Pläne'].map(s=>`<button class="${state.activityTab===s?'selected':''}" data-action="activity-tab" data-value="${s}">${s}${s==='Einladungen'&&invites.length?`<span class="count-badge">${invites.length}</span>`:''}</button>`).join('')}</div>${state.activityTab==='Einladungen'?`<div class="section-heading"><h2>Ein paar gute Gründe, Ja zu sagen.</h2></div><div class="invitation-list">${invites.length?invites.map(invitationCard).join(''):empty('Alle Einladungen beantwortet.','Dein nächster guter Plan wartet bestimmt schon.',null)}</div>`:`${searchBox('Finde deinen nächsten guten Plan …')}${chips(CATEGORIES,state.filter)}${state.activityTab==='Entdecken'?`<div class="activities-intro"><span class="tiny-label">WENIGER SCROLLEN. MEHR ERLEBEN.</span><h2>Mach mal<br><span>zusammen.</span></h2><div class="intro-people">${miniAvatars()}<p>Du musst niemanden kennen.<br>Nur Lust haben, dabei zu sein.</p></div>${icon('spark',74)}</div>`:''}<div class="section-heading"><h2>${state.activityTab==='Meine Pläne'?'Das hast du vor.':'Was geht, FHV?'}</h2><span>${posts.length} ${posts.length===1?'Plan':'Pläne'}</span></div><div class="post-grid activity-grid">${posts.length?posts.map(p=>postCard(p)).join(''):empty('Dein Kalender hat noch Platz.','Entdecke Aktivitäten oder starte deine eigene.',state.activityTab==='Meine Pläne'?'discover':'create',state.activityTab==='Meine Pläne'?'Aktivitäten entdecken':'Etwas starten')}</div>`}`; }
function profile() { const mine=state.posts.filter(p=>p.author_id===state.user.id);return `<section class="profile-card"><div class="profile-cover"><span class="profile-spark">${icon('spark',70)}</span><span class="tiny-label">EIN CAMPUS. VIELE GESCHICHTEN.</span></div><div class="profile-content">${avatar(state.user,'large')}<button class="btn outline small edit-profile" data-action="edit-profile">Profil bearbeiten</button><h2>${e(state.user.name)}</h2><p class="profile-course">${e(state.user.course||'FHV Community')}</p><span class="verified-label">${icon('shield',14)} ${isDemo()?'Demo-Profil':'FHV-Mail bestätigt'}</span><p class="profile-bio">${e(state.user.bio || 'Sag Hallo! Erzähle deinem Campus ein bisschen von dir.')}</p><div class="interest-chips">${(state.user.interests||[]).map(i=>`<span>${e(i)}</span>`).join('')}</div><div class="profile-stats"><div><strong>${state.joined.length}</strong><span>Gemeinsame Pläne</span></div><div><strong>${mine.length}</strong><span>Eigene Beiträge</span></div><div><strong>${state.saved.length}</strong><span>Gemerkt</span></div></div></div></section><div class="profile-menu"><button data-action="saved">${icon('bookmark')}<span><strong>Deine Merkliste</strong><small>Gute Ideen für später</small></span><span class="menu-count">${state.saved.length}</span>${icon('chevron',18)}</button><button data-action="my-posts">${icon('user')}<span><strong>Deine Beiträge</strong><small>Was du auf dem Campus teilst</small></span>${icon('chevron',18)}</button><button data-action="install">${icon('download')}<span><strong>Auf den Homescreen</strong><small>FHV Friends fühlt sich wie eine App an</small></span>${icon('chevron',18)}</button><button data-action="about">${icon('shield')}<span><strong>Über FHV Friends</strong><small>Community, Privatsphäre & Kontakt</small></span>${icon('chevron',18)}</button><button data-action="${isDemo()?'auth':'logout'}">${icon('logout')}<span><strong>${isDemo()?'Mit FHV-Mail anmelden':'Abmelden'}</strong><small>${isDemo()?'Werde Teil deines Campus':'Bis zum nächsten guten Plan'}</small></span>${icon('chevron',18)}</button></div>${isDemo()?'<p class="demo-profile-note">Dies ist ein Demo-Profil. Änderungen bleiben nur auf diesem Gerät.</p>':''}`; }
function rightRail() { const upcoming=state.posts.filter(p=>p.type==='activity'&&new Date(p.starts_at)>new Date()).sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at)).slice(0,3);return `<aside class="right-rail"><div class="rail-header"><span>DEIN CAMPUS-KOMPASS</span>${icon('sun',19)}</div><section class="rail-section"><div class="section-heading"><h2>Schon was vor?</h2><button class="icon-btn small" data-action="nav" data-tab="activities" aria-label="Alle Aktivitäten">${icon('chevron',18)}</button></div>${upcoming.map(p=>`<button class="upcoming" data-action="detail" data-id="${p.id}"><span class="rail-date"><strong>${new Date(p.starts_at).getDate()}</strong><small>${dateLabel(p.starts_at,{month:'short'}).replace(/\d+\.?\s*/,'')}</small></span><span><strong>${e(p.subtitle||p.title)}</strong><small>${timeLabel(p.starts_at)} · ${e(p.location)}</small></span></button>`).join('')}</section><section class="rail-connect"><span class="tiny-label">DEIN CAMPUS IST VOLLER MÖGLICHKEITEN.</span><h3>Einfach mal<br>Hallo sagen.</h3><p>Die nächste Freundschaft beginnt vielleicht mit deinem Plan.</p>${miniAvatars()}<button class="btn primary" data-action="create">${icon('plus',17)} Starte etwas</button></section><section class="rail-section help-rail"><span class="help-mark yellow">${icon('book',24)}</span><h3>Du musst das<br>nicht allein checken.</h3><p>Nachhilfe, ein Werkzeug oder eine helfende Hand.</p><button class="text-link" data-action="help">Campus fragen ${icon('chevron',15)}</button></section><div class="rail-footer">${icon('leaf',17)} Teilen verbindet. Und spart Ressourcen.</div></aside>`; }
function render() { $('#app').innerHTML=`<div class="app-shell">${sidebar()}<div class="main-shell">${statusBanner()}<div class="content-layout"><main id="main" tabindex="-1">${header()}<div class="page-content ${state.tab}-page">${state.loading?'<div class="loading-state"><span class="spinner"></span><p>Dein Campus lädt …</p></div>':({feed,trade,activities,profile}[state.tab]||feed)()}</div><footer class="page-foot">FHV Friends <span>·</span> Zusammen ist mehr drin.</footer></main>${state.tab!=='profile'?rightRail():''}</div></div>${nav()}</div>`; }
function navigate(tab) { state.tab=tab;state.filter='Alle';state.query='';history.replaceState(null,'',`#${tab}`);closeModal();render();window.scrollTo({top:0,behavior:'instant'}); }
function modal(title,body,{wide=false,footer='',label=title,cls=''}={}) { clearInterval(chatInterval); lastFocus=document.activeElement;$('#overlay').innerHTML=`<div class="modal-backdrop" data-action="backdrop"><section class="modal ${wide?'wide':''} ${cls}" role="dialog" aria-modal="true" aria-label="${e(label)}"><div class="modal-handle"></div><header class="modal-header"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Schließen">${icon('close')}</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;document.body.classList.add('modal-open');$('#overlay').querySelector('button,input,textarea,select')?.focus(); }
function closeModal() { if(state.overlay==='create'&&!state.editingId)saveDraft(false);clearInterval(chatInterval);state.overlay=null;state.selected=null;state.currentChat=null;$('#overlay').innerHTML='';document.body.classList.remove('modal-open');lastFocus?.isConnected&&lastFocus.focus(); }
async function detail(id) { const p=state.posts.find(x=>x.id===id);if(!p)return;state.overlay='detail';state.selected=id;const activity=p.type==='activity';const own=p.author_id===state.user.id; const expired=activity&&new Date(p.starts_at)<new Date();const content=`${p.art?`<div class="detail-art">${artwork(p.art)}<span class="detail-category ${activity?'blue':p.type==='help'?'yellow':'lavender'}">${e(activity?p.category:TYPES[p.type])}</span></div>`:''}<div class="detail-content"><div class="detail-topline">${authorLine(p)}${bookmarkButton(p)}</div><h2 class="detail-title">${e(p.subtitle||p.title)}</h2>${activity?`<div class="detail-date"><span class="date-block"><strong>${new Date(p.starts_at).getDate()}</strong><small>${dateLabel(p.starts_at,{month:'short'}).replace(/\d+\.?\s*/,'')}</small></span><div><strong>${dateLabel(p.starts_at,{weekday:'long',year:'numeric'})}</strong><span>${timeLabel(p.starts_at)} Uhr · ${p.price?`${p.price} €`:'Kostenlos dabei'}</span><span>${icon('map',13)} ${e(p.location)}</span></div><button class="icon-btn" data-action="calendar" data-id="${p.id}" aria-label="Im Kalender speichern">${icon('calendar',21)}</button></div>`:`<div class="detail-listing-meta"><span>${icon('map',17)} ${e(p.location)}</span><strong>${p.price?`${p.price} €`:'Für 0 €. Für dich.'}</strong></div>`}<h3>${activity?'Ein guter Plan fängt mit dir an.':p.type==='help'?'Zusammen geht’s leichter.':'Ein zweites Zuhause wartet.'}</h3><p class="detail-description">${e(p.description).replace(/\n/g,'<br>')}</p>${p.type==='food'?'<div class="info-box"><span>'+icon('leaf',22)+'</span><div><strong>Bitte persönlich übergeben.</strong><p>Kläre Zutaten, Allergene und Abholzeit direkt mit der anbietenden Person.</p></div></div>':''}${activity?`<div class="detail-attendees yellow"><div>${miniAvatars()}<strong>${count(p)} ${count(p)===1?'Person ist':'Studierende sind'} dabei</strong></div><p>${p.capacity?`${Math.max(0,p.capacity-count(p))} von ${p.capacity} Plätzen frei.`:'Komm allein. Geh mit neuen Freunden.'}</p></div>${own?'<div class="host-actions"><button class="btn outline full" data-action="invite-people" data-id="'+p.id+'">'+icon('people',18)+' Leute einladen</button><button class="btn soft full" data-action="group-chat" data-id="'+p.id+'">'+icon('chat',18)+' Gruppenchat öffnen</button></div>':''}${joined(p.id)?`<div class="joined-note">${icon('check',18)} Steht in deinen Plänen. Wir freuen uns auf dich!</div><div class="detail-secondary-actions"><button class="text-link" data-action="group-chat" data-id="${p.id}">${icon('chat',16)} Gruppenchat</button><button class="text-link danger" data-action="join" data-id="${p.id}">Doch nicht dabei</button></div>`:''}`:''}<section class="comments-section"><h3>Fragen & Vorfreude <span id="comment-count"></span></h3><div id="comments-list"><p class="muted">${isDemo()?'Noch keine Kommentare. Sag als Erste:r Hallo.':'Kommentare laden …'}</p></div><form id="comment-form" data-post="${p.id}" class="comment-form"><input name="body" required minlength="1" maxlength="1000" placeholder="Stell eine Frage oder sag Hallo …" aria-label="Kommentar schreiben"><button class="icon-btn dark" type="submit" aria-label="Kommentar senden">${icon('send',18)}</button></form></section></div>`;
modal('Details',content,{wide:true,cls:'detail-modal',footer:`<div class="detail-footer-copy"><strong>${activity?(expired?'Aktivität beendet':full(p)?'Alle Plätze belegt':'${FREE}'):p.status==='reserved'?'Bereits reserviert':p.price?`${p.price} €`:'Kostenlos'}</strong><span>${activity?'Neue Leute sind willkommen.':e(p.location)}</span></div><button class="btn primary" data-action="${own?'share':activity?'join':'contact'}" data-id="${p.id}" ${expired||full(p)?'disabled':''}>${own?icon('share',17)+' Teilen':activity?(joined(p.id)?icon('check',17)+' Du bist dabei':'Bin dabei'):(p.type==='help'?'Nachricht schreiben':'Kontakt aufnehmen')}</button>`.replace('${FREE}',p.price?`${p.price} €`:'Für alle offen')});
loadComments(id);
}
async function loadComments(id) { try { const comments = isDemo()?(state.comments[id]||[]):await api.comments(id);if(state.selected!==id)return;$('#comments-list').innerHTML=comments.length?comments.map(c=>`<div class="comment">${avatar(c.author||state.user,'mini')}<div><strong>${e(c.author?.name||state.user.name)} <small>${relative(c.created_at)}</small></strong><p>${e(c.body)}</p></div></div>`).join(''):'<p class="muted">Noch keine Kommentare. Sag als Erste:r Hallo.</p>';$('#comment-count').textContent=comments.length||'';}catch{if($('#comments-list'))$('#comments-list').innerHTML='<p class="muted">Kommentare konnten nicht geladen werden.</p>';} }
function createModal(type=state.createType,editingId=null) { state.overlay='create';state.createType=type;state.editingId=editingId;const editing=state.posts.find(p=>p.id===editingId);const draft=editing?{...editing,date:editing.starts_at?new Date(new Date(editing.starts_at).getTime()-new Date(editing.starts_at).getTimezoneOffset()*60000).toISOString().slice(0,10):'',time:editing.starts_at?timeLabel(editing.starts_at):''}:readLocal('fhv-draft',{});const title=type==='activity'?'Gute Pläne fangen hier an.':type==='help'?'Frag deinen Campus.':'Teile etwas Gutes.';const tomorrow=new Date(Date.now()+86400000); const date=new Date(tomorrow.getTime()-tomorrow.getTimezoneOffset()*60000).toISOString().slice(0,10);modal(editing?'Beitrag bearbeiten':'Etwas starten',`<div class="create-intro"><span class="tiny-label">VON EINER IDEE ZU EINEM GUTEN PLAN</span><h2>${title}</h2><p>Ein kleiner Beitrag. Vielleicht eine große Verbindung.</p></div><div class="create-types">${Object.entries(TYPES).map(([key,label])=>`<button type="button" class="type-option ${state.createType===key?'selected':''}" data-action="create-type" data-value="${key}" ${editing?'disabled':''}>${icon({activity:'calendar',trade:'trade',food:'leaf',help:'book',life:'people'}[key],18)} ${label}</button>`).join('')}</div><form id="create-form"><input type="hidden" name="type" value="${type}"><label>Dein Titel<input name="title" required minlength="4" maxlength="100" value="${e(draft.type===type?draft.title||'':'')}" placeholder="${({activity:'Zum Beispiel: Morgen zusammen bouldern?',trade:'Zum Beispiel: Eine Lampe sucht ein Zuhause',food:'Zum Beispiel: Eine Portion Pasta zu viel',help:'Zum Beispiel: Hilfe bei Technischer Mechanik',life:'Was möchtest du mit dem Campus teilen?'})[type]}"></label><label>Erzähl ein bisschen mehr<textarea name="description" required minlength="10" maxlength="3000" rows="4" placeholder="Was hast du vor? Was sollten andere wissen?">${e(draft.type===type?draft.description||'':'')}</textarea></label>${type==='activity'?`<div class="form-row"><label>Datum<input type="date" name="date" min="${date}" value="${draft.type===type&&draft.date>=date?draft.date:date}" required></label><label>Uhrzeit<input type="time" name="time" value="${e(draft.type===type?draft.time||'18:00':'18:00')}" required></label></div>`:''}<label>${type==='activity'?'Treffpunkt':'Übergabe / Ort'}<input name="location" list="campus-spots" maxlength="150" required placeholder="Wähle einen Campus-Spot oder eigenen Ort" value="${e(draft.type===type?draft.location||'':'')}"><datalist id="campus-spots">${SPOTS.map(s=>`<option value="${s.name} · FHV">`).join('')}<option value="Nach Vereinbarung"></datalist></label><div class="form-row"><label>Kategorie<select name="category">${CATEGORIES.filter(x=>x!=='Alle').map(c=>`<option ${draft.category===c?'selected':''}>${c}</option>`).join('')}</select></label>${type==='activity'?`<label>Max. Personen<input type="number" name="capacity" min="2" max="500" placeholder="Offen für alle" value="${e(draft.capacity||'')}"></label>`:type==='trade'||type==='help'?`<label>Preis in €<input type="number" name="price" min="0" max="10000" step="0.01" value="${Number(draft.price||0)}"></label>`:''}</div>${type==='help'?'<label>Du möchtest …<select name="help_direction"><option value="offer">Hilfe anbieten</option><option value="request">Um Hilfe bitten</option></select></label>':''}${type==='food'?'<div class="info-box">'+icon('leaf',20)+'<p>Bitte Zutaten und Allergene in der Beschreibung nennen. Persönliche Übergabe vereinbaren.</p></div>':''}${isOh()?'<label class="check-label"><input type="checkbox" name="pinned"> Als ÖH veröffentlichen und oben im Feed anpinnen</label>':''}<div class="form-error" id="create-error" role="alert"></div><div class="publishing-as">${avatar(state.user,'mini')}<span>Du postest als <strong>${e(state.user.name)}</strong><small>${isDemo()?'Demo · bleibt auf diesem Gerät':'Für die FHV Community'}</small></span><button class="text-link" type="button" data-action="save-draft">Entwurf speichern</button></div><button type="submit" class="btn primary full">${icon('plus',18)} ${editing?'Änderungen speichern':isDemo()?'In der Demo veröffentlichen':'Mit dem Campus teilen'}</button></form>`,{wide:true,cls:'create-modal'});if(editing){const help=$('[name=help_direction]');if(help)help.value=editing.help_direction||'offer';const pin=$('[name=pinned]');if(pin)pin.checked=editing.pinned;} }
function authModal(mode='login') { state.overlay='auth';state.authMode=mode;modal('',`<div class="auth-brand">${logo}</div><div class="auth-illustration">${miniAvatars()}<span class="blue">${icon('spark',31)}</span></div><span class="tiny-label">DEIN CAMPUS. DEINE LEUTE.</span><h2>${mode==='signup'?'Dein Platz ist schon frei.':'Schön, dass du da bist.'}</h2><p>Aktivitäten starten, Dinge weitergeben und neue Leute kennenlernen. Nur für die FHV Community.</p><div class="segment-control"><button class="${mode==='login'?'selected':''}" data-action="auth-mode" data-value="login">Anmelden</button><button class="${mode==='signup'?'selected':''}" data-action="auth-mode" data-value="signup">Konto erstellen</button></div><form id="auth-form">${mode==='signup'?'<label>Dein Name<input name="name" autocomplete="name" placeholder="Wie heißt du?" required minlength="2" maxlength="80"></label>':''}<label>FHV-Mailadresse<input type="email" name="email" autocomplete="email" placeholder="vorname.nachname@students.fhv.at" required></label><label>Passwort<input name="password" type="password" autocomplete="${mode==='signup'?'new-password':'current-password'}" minlength="${mode==='signup'?12:1}" required placeholder="${mode==='signup'?'Mindestens 12 Zeichen':'Dein Passwort'}"></label>${mode==='signup'?'<p class="form-hint">Du erhältst eine Bestätigungsmail. Erst danach kannst du dich anmelden.</p>':''}<div class="form-error" id="auth-error" role="alert"></div>${!configured?'<div class="setup-notice">'+icon('settings',20)+'<span><strong>Live-Anmeldung noch nicht freigeschaltet.</strong> Die App ist vorbereitet. Datenbank und Mailversand müssen noch verbunden werden.</span></div>':''}<button class="btn primary full" type="submit" ${!configured?'disabled':''}>${mode==='signup'?'Konto erstellen':'Mit FHV-Mail anmelden'}</button></form>${mode==='login'?'<button class="text-link auth-demo" data-action="recover">Passwort vergessen?</button>':''}<div class="auth-secure">${icon('shield',15)} @students.fhv.at & @fhv.at · Mailbestätigung erforderlich</div><button class="text-link auth-demo" data-action="close">Erst einmal die Demo erkunden</button>`,{cls:'auth-modal'}); }
function editProfile() { state.overlay='edit-profile';modal('Dein Profil',`<div class="edit-profile-avatar">${avatar(state.user,'large')}<p>Zeig deinem Campus, wer du bist.</p></div><form id="profile-form"><label>Dein Name<input name="name" value="${e(state.user.name)}" required minlength="2" maxlength="80"></label><label>Studiengang<input name="course" value="${e(state.user.course||'')}" placeholder="Zum Beispiel: Mechatronik · Master" maxlength="100"></label><label>Ein bisschen über dich<textarea name="bio" maxlength="400" rows="3" placeholder="Wofür bist du zu haben?">${e(state.user.bio||'')}</textarea></label><label>Deine Interessen <small>Mit Komma trennen</small><input name="interests" maxlength="200" value="${e((state.user.interests||[]).join(', '))}" placeholder="Bouldern, Kaffee, Musik …"></label><fieldset class="color-picker"><legend>Deine Farbe</legend>${['blue','yellow','lavender','coral','green'].map(c=>`<label class="color-option ${c}"><input type="radio" name="color" value="${c}" ${state.user.color===c?'checked':''}><span>${state.user.color===c?icon('check',17):''}</span><span class="sr-only">${c}</span></label>`).join('')}</fieldset><div class="form-error" id="profile-error" role="alert"></div><button type="submit" class="btn primary full">Änderungen speichern</button></form>`); }
function notifications() { state.noticeRead=true;render();state.overlay='notifications';modal('Für dich auf dem Campus',`<p class="modal-lead">Einladungen, die deinen Tag besser machen könnten.</p><div class="notification-list">${pendingInvites().length?pendingInvites().map(invitationCard).join(''):empty('Du bist auf dem neuesten Stand.','Neue Einladungen findest du hier.',null)}</div>`); }
function savedModal(own=false) { state.overlay=own?'my-posts':'saved';const posts=state.posts.filter(p=>own?p.author_id===state.user.id:state.saved.includes(p.id));modal(own?'Deine Beiträge':'Für später gemerkt',`<div class="saved-list">${posts.length?posts.map(p=>`<button class="saved-row" data-action="detail" data-id="${p.id}"><span class="saved-thumb">${p.art?artwork(p.art):icon('spark',25)}</span><span><small>${e(TYPES[p.type])}</small><strong>${e(p.subtitle||p.title)}</strong><small>${e(p.location)}</small></span>${icon('chevron',17)}</button>`).join(''):empty(own?'Deine erste gute Idee?':'Platz für gute Ideen.','Mit einem kleinen Beitrag kann viel anfangen.',own?'create':'close',own?'Etwas starten':'Campus entdecken')}</div>`); }
function about() { state.overlay='about';modal('FHV Friends',`<div class="about-brand">${logo}</div><h2>Zusammen ist mehr drin.</h2><p>Eine studentische Campus-App für die FHV in Dornbirn. Aktivitäten, Dinge und Wissen teilen — und dabei neue Leute kennenlernen.</p><div class="info-box blue">${icon('people',25)}<div><strong>Ein gutes Miteinander.</strong><p>Sei respektvoll. Halte Absprachen ein. Teile keine privaten Daten anderer Personen. Triff dich für Übergaben an einem öffentlichen Ort.</p></div></div><h3>Deine Privatsphäre</h3><p>Im Livebetrieb sind Beiträge und Profile nur für bestätigte FHV-Konten sichtbar. Direktnachrichten können nur die beteiligten Personen lesen. Deine Mailadresse wird nicht im Profil angezeigt. Es gibt keine Werbetracker.</p><h3>Aktueller Stand</h3><p>${isDemo()?'Du nutzt die Demo mit fiktiven Personen und Beispieldaten. Eingaben bleiben im Browser dieses Geräts. Es werden keine Nachrichten an echte Personen verschickt.':'Du nutzt die Live-App. Deine Inhalte werden in der verbundenen Supabase-Datenbank gespeichert.'}</p><h3>Transparenz</h3><p>Studentischer Prototyp. Die FHV-Bildmarke ist Eigentum der FH Vorarlberg. Der Prototyp ist kein offizieller Dienst der Hochschule. Verantwortliche Stelle, Impressum und abschließende Datenschutzhinweise werden vor dem Start mit echten Nutzerdaten ergänzt.</p>${isDemo()?'<button class="btn outline full" data-action="reset-demo">Demo auf diesem Gerät zurücksetzen</button>':''}`); }
async function toggleSave(id) { const on=!state.saved.includes(id); if(!isDemo())await api.toggle('bookmarks',id,state.user.id,on); state.saved=on?[...state.saved,id]:state.saved.filter(x=>x!==id);persist();render();if(state.overlay==='detail')detail(id);toast(on?'Für später gemerkt.':'Aus deiner Merkliste entfernt.'); }
async function toggleLike(id) { const p=state.posts.find(x=>x.id===id);if(!p)return;const on=!state.liked.includes(id);if(!isDemo())await api.toggle('likes',id,state.user.id,on);state.liked=on?[...state.liked,id]:state.liked.filter(x=>x!==id);p.likes=Math.max(0,Number(p.likes||0)+(on?1:-1));persist();render(); }
async function joinActivity(id) { const p=state.posts.find(x=>x.id===id);if(!p||p.type!=='activity')return;const on=!joined(id);if(on&&full(p)){toast('Alle Plätze sind schon belegt.');return;}if(!isDemo())await api.rpc('set_attendance',{activity_id:id,attending:on});state.joined=on?[...state.joined,id]:state.joined.filter(x=>x!==id);p.join_count=Math.max(0,count(p)+(on?1:-1));persist();render();if(state.overlay==='detail')detail(id);toast(on?'Du bist dabei! Steht jetzt in deinen Plänen.':'Du hast dich abgemeldet.'); }
async function respondInvite(id,status) { const inv=state.invitations.find(x=>x.id===id);if(!inv)return;const p=state.posts.find(x=>x.id===inv.post_id);if(status==='accepted'&&p&&full(p)){toast('Diese Aktivität ist inzwischen ausgebucht.');return;}if(!isDemo())await api.invitationStatus(id,status);if(status==='accepted'&&!joined(inv.post_id)){state.joined.push(inv.post_id);if(p)p.join_count=count(p)+1;}inv.status=status;persist();render();if(state.overlay==='notifications')notifications();toast(status==='accepted'?'Einladung angenommen. Schön, dass du dabei bist!':'Einladung abgelehnt.'); }
async function contact(id) { const p=state.posts.find(x=>x.id===id);if(!p)return;if(p.author_id===state.user.id){toast('Das ist dein eigener Beitrag.');return;}if(!isDemo()){const chat=await api.rpc('start_direct_chat',{other_user:p.author_id});return openChat(chat);}let chat=state.chats.find(c=>!c.post_id&&c.peer_id===p.author_id);if(!chat){chat={id:crypto.randomUUID(),peer_id:p.author_id,title:p.author.name,created_at:new Date().toISOString(),color:p.author.color};state.chats.push(chat);state.messages[chat.id]=[];persist();}openChat(chat.id); }
async function inbox() { state.overlay='inbox';if(!isDemo())state.chats=await api.chats();modal('Deine Nachrichten',`<p class="modal-lead">Die besten Pläne beginnen mit einem Hallo.</p>${isDemo()?'<div class="inline-demo">Demo · Nachrichten bleiben auf diesem Gerät.</div>':''}<div class="chat-list">${state.chats.length?state.chats.map(c=>{const messages=state.messages[c.id]||[];return `<button class="chat-row" data-action="chat" data-id="${c.id}">${avatar({name:c.title,color:c.color||'blue'})}<span><strong>${e(c.title||'Campus-Chat')}</strong><small>${e(messages.at(-1)?.body||'Sag einfach mal Hallo.')}</small></span>${icon('chevron',18)}</button>`;}).join(''):empty('Hier fangen Gespräche an.','Öffne einen Beitrag und schreibe der Person eine Nachricht.',null)}</div>`); }
async function openChat(id) { if(!isDemo()&&!state.chats.find(c=>c.id===id))state.chats=await api.chats();const chat=state.chats.find(c=>c.id===id);state.currentChat=id;state.overlay='chat';modal(`<button class="text-link" data-action="inbox" aria-label="Zurück zu Nachrichten">${icon('chevron',20,'back-icon')}</button> ${e(chat?.title||'Campus-Chat')}`,`${isDemo()?'<div class="inline-demo">Demo-Chat · Keine echten Empfänger oder automatischen Antworten.</div>':''}<div class="chat-messages" id="chat-messages" aria-live="polite"></div><form id="message-form" class="message-form"><input name="body" required maxlength="2000" aria-label="Nachricht" autocomplete="off" placeholder="Einfach mal Hallo sagen …"><button class="icon-btn dark" type="submit" aria-label="Nachricht senden">${icon('send',20)}</button></form>`,{cls:'chat-modal'});await loadMessages(id);if(!isDemo())chatInterval=setInterval(()=>loadMessages(id),8000); }
async function loadMessages(id) { if(state.currentChat!==id)return;try{const messages=isDemo()?(state.messages[id]||[]):await api.messages(id);if(state.currentChat!==id)return;state.messages[id]=messages;const list=$('#chat-messages');if(!list)return;const nearBottom=list.scrollHeight-list.scrollTop-list.clientHeight<80;list.innerHTML=messages.length?messages.map(m=>`<div class="message ${m.author_id===state.user.id?'mine':''}"><p>${e(m.body)}</p><small>${e(m.author?.name||state.user.name)} · ${timeLabel(m.created_at)}</small></div>`).join(''):'<div class="chat-empty">'+icon('chat',42)+'<h3>Ein Hallo ist ein guter Anfang.</h3><p>Kläre hier alles für euren nächsten Plan.</p></div>';if(nearBottom)list.scrollTop=list.scrollHeight;}catch{toast('Nachrichten konnten nicht geladen werden.');} }
async function groupChat(id) { const p=state.posts.find(x=>x.id===id);if(!p)return;if(!isDemo()){const chat=await api.rpc('activity_chat',{activity_id:id});return openChat(chat);}let chat=state.chats.find(c=>c.post_id===id);if(!chat){chat={id:crypto.randomUUID(),post_id:id,title:p.subtitle||p.title,created_at:new Date().toISOString(),color:'yellow'};state.chats.push(chat);state.messages[chat.id]=[];persist();}openChat(chat.id); }
function install() { if(deferredInstall){deferredInstall.prompt();deferredInstall.userChoice.then(()=>deferredInstall=null);return;}modal('Dein Campus auf dem Homescreen',`<div class="install-icon blue">${fhvMark}</div><h2>Ein Tipp. Schon mittendrin.</h2><p>FHV Friends kannst du direkt als Web-App installieren. Ohne App Store.</p><div class="install-step"><strong>iPhone & iPad</strong><p>In Safari öffnen, auf <b>Teilen</b> tippen und <b>Zum Home-Bildschirm</b> auswählen.</p></div><div class="install-step"><strong>Android</strong><p>In Chrome das Menü öffnen und <b>App installieren</b> oder <b>Zum Startbildschirm hinzufügen</b> wählen.</p></div><div class="install-step"><strong>Am Computer</strong><p>In Chrome oder Edge rechts in der Adressleiste auf das Installationssymbol klicken.</p></div>`); }
function postMenu(id) {const p=state.posts.find(x=>x.id===id);if(!p)return;const own=p.author_id===state.user.id;state.selected=id;state.overlay='post-menu';modal('Zum Beitrag',`<div class="action-list"><button data-action="share" data-id="${id}">${icon('share')} Beitrag teilen</button><button data-action="save" data-id="${id}">${icon('bookmark')} ${state.saved.includes(id)?'Nicht mehr merken':'Für später merken'}</button>${isOh()?`<button data-action="pin" data-id="${id}">${icon('pin')} ${p.pinned?'Nicht mehr anpinnen':'Oben im Feed anpinnen'}</button>`:''}${own?`<button data-action="edit-post" data-id="${id}">${icon('settings')} Beitrag bearbeiten</button><button class="danger" data-action="confirm-delete" data-id="${id}">${icon('trash')} Beitrag löschen</button>`:`<button data-action="report" data-id="${id}">${icon('flag')} Beitrag melden</button>`}</div>`); }
async function share(id) { const p=state.posts.find(x=>x.id===id);const url=new URL(location.href);url.hash=`post/${id}`; if(navigator.share){try{await navigator.share({title:p?.title||'FHV Friends',text:'Bist du dabei? Auf FHV Friends.',url:url.href});}catch(ex){if(ex.name!=='AbortError')toast('Teilen ist gerade nicht verfügbar.');}}else{try{await navigator.clipboard.writeText(url.href);toast('Link kopiert. Jetzt jemanden mitnehmen!');}catch{modal('Beitrag teilen',`<label>Link zum Kopieren<input readonly value="${e(url.href)}"></label>`);}} }
function calendar(id) { const p=state.posts.find(x=>x.id===id);if(!p?.starts_at)return;const url=URL.createObjectURL(new Blob([makeICS(p)],{type:'text/calendar;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='fhv-friends.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Kalendereintrag heruntergeladen.'); }
async function loadLive(user) { state.loading=true;state.mode='live';render();try { const [profile,role,posts,userState,memberships]=await Promise.all([api.profile(user.id),api.role(),api.posts(),api.state(user.id),api.memberships()]);state.user={...profile,id:user.id,role};state.posts=posts.map(p=>({...p,price:Number(p.price||0),likes:Number(p.likes||0)}));Object.assign(state,userState);const counts={};memberships.forEach(m=>counts[m.post_id]=(counts[m.post_id]||0)+1);state.posts.forEach(p=>p.join_count=counts[p.id]||0); }catch(error){state.posts=[];toast(error.message);}finally{state.loading=false;render();} }
async function invitePeople(id) { state.overlay='invite-people';const people=isDemo()?Object.values(PEOPLE).filter(p=>p.role!=='oh'):await api.people();modal('Zusammen ist besser',`<p class="modal-lead">Lade Leute zu deiner Aktivität ein.</p><div class="people-list">${people.filter(p=>p.id!==state.user.id).map(p=>`<div class="people-row">${avatar(p)}<span><strong>${e(p.name)}</strong><small>${e(p.course||'FHV Community')}</small></span><button class="btn soft small" data-action="send-invite" data-post="${id}" data-id="${p.id}">Einladen</button></div>`).join('')}</div>${isDemo()?'<div class="inline-demo">Demo · Es werden keine echten Einladungen verschickt.</div>':''}`); }
const actions = {
 nav:el=>navigate(el.dataset.tab),close:closeModal,backdrop:el=>{if(el===eventTarget)closeModal();},
 filter:el=>{state.filter=el.dataset.value;render();},
 'activity-tab':el=>{state.activityTab=el.dataset.value;state.filter='Alle';state.query='';render();},
 'trade-tab':el=>{state.tradeTab=el.dataset.value;state.filter='Alle';state.query='';render();},
 detail:el=>detail(el.dataset.id),create:()=>createModal(),
 'create-type':el=>{saveDraft(false);createModal(el.dataset.value);},
 'save-draft':()=>saveDraft(true),auth:()=>authModal(),
 'auth-mode':el=>authModal(el.dataset.value),recover:()=>{state.overlay='recover';modal('Passwort zurücksetzen',`<p>Wir schicken dir einen Link an deine FHV-Mailadresse.</p><form id="recovery-form"><label>FHV-Mailadresse<input name="email" type="email" autocomplete="email" required placeholder="name@students.fhv.at"></label><div class="form-error" id="recovery-error" role="alert"></div><button class="btn primary full" type="submit" ${!configured?'disabled':''}>Link anfordern</button></form>`);},
 'edit-profile':editProfile,saved:()=>savedModal(), 'my-posts':()=>savedModal(true),
 help:()=>{navigate('trade');state.filter='Hilfe';render();},
 discover:()=>{navigate('activities');state.activityTab='Entdecken';render();},
 save:el=>toggleSave(el.dataset.id),like:el=>toggleLike(el.dataset.id),join:el=>joinActivity(el.dataset.id),
 accept:el=>respondInvite(el.dataset.id,'accepted'),decline:el=>respondInvite(el.dataset.id,'declined'),
 'post-menu':el=>postMenu(el.dataset.id),'edit-post':el=>{const p=state.posts.find(x=>x.id===el.dataset.id);if(p)createModal(p.type,p.id);},notifications,inbox,chat:el=>openChat(el.dataset.id),
 contact:el=>contact(el.dataset.id),'group-chat':el=>groupChat(el.dataset.id),
 share:el=>share(el.dataset.id),calendar:el=>calendar(el.dataset.id),install,about,
 'invite-people':el=>invitePeople(el.dataset.id),
 'send-invite':async el=>{if(!isDemo())await api.invitations(el.dataset.post,el.dataset.id,state.user.id);el.disabled=true;el.textContent='Eingeladen';toast(isDemo()?'Einladung in der Demo vorgemerkt.':'Einladung verschickt.');},
 'confirm-delete':el=>modal('Beitrag löschen?',`<p>Dein Beitrag und zugehörige Zusagen und Kommentare werden gelöscht.</p><button class="btn primary full" data-action="delete" data-id="${el.dataset.id}">Beitrag löschen</button>`),
 delete:async el=>{const id=el.dataset.id;if(!isDemo())await api.deletePost(id);state.posts=state.posts.filter(p=>p.id!==id);state.joined=state.joined.filter(x=>x!==id);state.saved=state.saved.filter(x=>x!==id);persist();closeModal();render();toast('Beitrag gelöscht.');},
 pin:async el=>{const p=state.posts.find(p=>p.id===el.dataset.id);if(!isOh()||!p)return;if(!isDemo())await api.pinPost(p.id,!p.pinned);p.pinned=!p.pinned;persist();closeModal();render();toast(p.pinned?'Oben im Feed angepinnt.':'Beitrag nicht mehr angepinnt.');},
 report:el=>modal('Beitrag melden',`<p>Hilf uns, den Campus respektvoll zu halten.</p><form id="report-form" data-id="${el.dataset.id}"><label>Was ist los?<select name="reason"><option>Unangemessener Inhalt</option><option>Spam oder Werbung</option><option>Irreführendes Angebot</option><option>Belästigung</option><option>Sonstiges</option></select></label><button class="btn primary full" type="submit">${isDemo()?'Meldung in Demo testen':'Meldung abschicken'}</button></form>`),
 'reset-demo':()=>modal('Demo zurücksetzen?',`<p>Deine lokalen Demo-Beiträge, Nachrichten und Profiländerungen werden entfernt.</p><button class="btn primary full" data-action="reset-confirm">Demo zurücksetzen</button>`),
 'reset-confirm':()=>{localStorage.removeItem('fhv-demo-v1');localStorage.removeItem('fhv-draft');location.href=location.pathname;},
 logout:async()=>{await api.logout();state.mode='demo';Object.assign(state,{user:{...DEMO_USER},posts:demoPosts(),joined:['hike'],saved:[],liked:[],comments:{},chats:[],messages:{},invitations:[]});closeModal();navigate('feed');toast('Du bist abgemeldet.');},
};
let eventTarget;
document.addEventListener('click',async event=>{
 const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const action=el.dataset.action;if(!actions[action])return;
 eventTarget=event.target;if(action==='backdrop'&&event.target!==el)return;
 if(el.dataset.pending)return;el.dataset.pending='true';
 try { await actions[action](el); } catch(error) { toast(error.name==='TimeoutError'?'Der Campus braucht gerade etwas länger. Bitte erneut versuchen.':error.message||'Das hat nicht geklappt. Bitte versuche es erneut.'); }
 finally{delete el.dataset.pending;}
});
function saveDraft(show) { const form=$('#create-form');if(!form||state.editingId)return;const draft=Object.fromEntries(new FormData(form));saveLocal('fhv-draft',draft);if(show)toast('Entwurf auf diesem Gerät gespeichert.'); }
document.addEventListener('input',event=>{
 if(event.target.id==='search'){state.query=event.target.value;const pos=event.target.selectionStart;render();const input=$('#search');input?.focus();try{input?.setSelectionRange(pos,pos);}catch{}}
 if(event.target.closest('#create-form'))saveDraft(false);
});
document.addEventListener('submit',async event=>{
 const form=event.target;if(!['create-form','auth-form','profile-form','comment-form','message-form','report-form','recovery-form','password-form'].includes(form.id))return;
 event.preventDefault();if(form.dataset.pending)return;form.dataset.pending='true';const submit=form.querySelector('[type="submit"]');if(submit)submit.disabled=true;
 const values=Object.fromEntries(new FormData(form));
 try {
  if(form.id==='create-form') {
   const starts_at=values.date&&values.time?new Date(`${values.date}T${values.time}`).toISOString():null;
   const post={type:values.type,title:values.title.trim(),description:values.description.trim(),location:values.location.trim(),category:values.category||'Campus',starts_at,capacity:values.capacity?Number(values.capacity):null,price:Number(values.price||0),help_direction:values.help_direction||null,pinned:isOh()&&values.pinned==='on'};
   const error=validatePost(post);if(error)throw new Error(error);
   let result;
   if(!isDemo())result=(state.editingId?await api.updatePost(state.editingId,post):await api.createPost({...post,author_id:state.user.id}))?.[0];
   else result={...post,id:crypto.randomUUID(),author_id:state.user.id,created_at:new Date().toISOString(),status:'open',art:{activity:{Outdoor:'mountain',Sport:'run',Food:'coffee',Lernen:'study',Kultur:'boulder',Campus:'coffee'}[post.category]||'coffee',trade:'lamp',food:'salad',help:'math',life:'study'}[post.type]};
   if(state.editingId){const existing=state.posts.find(p=>p.id===state.editingId);Object.assign(existing,post,result?{...result,id:existing.id}:{});}else state.posts.unshift({...result,author:state.user,join_count:0,likes:0});state.editingId=null;state.overlay=null;localStorage.removeItem('fhv-draft');persist();navigate(post.type==='activity'?'activities':['help','food','trade'].includes(post.type)?'trade':'feed');toast(isDemo()?'Dein Beitrag ist in der Demo veröffentlicht.':'Dein Campus hat einen guten Plan mehr.');
  } else if(form.id==='auth-form') {
   if(state.authMode==='signup') { const data=await api.signup(values.email,values.password,values.name);if(data.session){throw new Error('Bitte E-Mail-Bestätigung im Projekt aktivieren, bevor die App live geht.');}modal('Fast geschafft.',`<div class="auth-mail-icon blue">${icon('mail',38)}</div><h2>Einmal Postfach checken.</h2><p>Falls die Registrierung möglich ist, erhältst du eine Bestätigungsmail an <strong>${e(values.email)}</strong>. Öffne den Link und melde dich danach an.</p><button class="btn primary full" data-action="auth">Zur Anmeldung</button>`); }
   else { const user=await api.login(values.email,values.password);if(!user.email_confirmed_at){await api.logout();throw new Error('Bestätige bitte zuerst deine FHV-Mailadresse.');}closeModal();await loadLive(user);toast('Willkommen auf deinem Campus!'); }
  } else if(form.id==='profile-form') {
   const profile={name:values.name.trim(),course:values.course.trim(),bio:values.bio.trim(),interests:values.interests.split(',').map(i=>i.trim()).filter(Boolean).slice(0,8),color:values.color||'blue'};
   if(!isDemo())await api.saveProfile(state.user.id,profile);Object.assign(state.user,profile);state.posts.forEach(p=>{if(p.author_id===state.user.id)p.author=state.user;});persist();closeModal();render();toast('Dein Profil ist aktualisiert.');
  } else if(form.id==='comment-form') {
   const body=values.body.trim();if(!body)return;const id=form.dataset.post;if(!isDemo())await api.comment(id,state.user.id,body);else{state.comments[id]??=[];state.comments[id].push({id:crypto.randomUUID(),author:state.user,body,created_at:new Date().toISOString()});persist();}form.reset();await loadComments(id);
  } else if(form.id==='message-form') {
   const body=values.body.trim(),id=state.currentChat;if(!body||!id)return;if(!isDemo())await api.send(id,state.user.id,body);else{state.messages[id]??=[];state.messages[id].push({id:crypto.randomUUID(),author_id:state.user.id,body,created_at:new Date().toISOString()});persist();}form.reset();await loadMessages(id);const list=$('#chat-messages');if(list)list.scrollTop=list.scrollHeight;
  } else if(form.id==='recovery-form') {await api.recover(values.email);modal('Prüfe dein Postfach.',`<p>Falls ein Konto existiert, erhältst du eine E-Mail mit einem Link zum Zurücksetzen.</p><button class="btn primary full" data-action="auth">Zur Anmeldung</button>`);
  } else if(form.id==='password-form') {await api.updatePassword(values.password);closeModal();toast('Dein Passwort ist aktualisiert.');
  } else if(form.id==='report-form') {
   if(!isDemo())await api.report(form.dataset.id,state.user.id,values.reason);closeModal();toast(isDemo()?'Demo-Meldung getestet. Es wurde nichts verschickt.':'Danke. Deine Meldung wird geprüft.');
  }
 } catch(error) {const target=$({ 'create-form':'#create-error','auth-form':'#auth-error','profile-form':'#profile-error','recovery-form':'#recovery-error','password-form':'#password-error'}[form.id]||'#nonexistent');if(target)target.textContent=error.message;else toast(error.message);}
 finally{delete form.dataset.pending;if(submit?.isConnected)submit.disabled=false;}
});
document.addEventListener('keydown',event=>{
 if(event.key==='Escape'){if(state.overlay==='create')saveDraft(false);closeModal();}
 if(event.key==='/'&&!/INPUT|TEXTAREA|SELECT/.test(document.activeElement?.tagName)){event.preventDefault();$('#search')?.focus();}
 if(event.key==='Tab'&&$('#overlay .modal')){const nodes=Array.from($('#overlay').querySelectorAll('button:not([disabled]),input:not([disabled]),textarea,select,[tabindex="0"]')).filter(n=>n.getClientRects().length);const first=nodes[0],last=nodes.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}
});
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstall=event;});
window.addEventListener('online',()=>toast('Du bist wieder online.'));
window.addEventListener('offline',()=>toast('Du bist offline. Bereits geladene Inhalte bleiben verfügbar.'));
window.addEventListener('hashchange',()=>{const hash=location.hash.slice(1);if(hash.startsWith('post/'))detail(hash.slice(5));else if(['feed','trade','activities','profile'].includes(hash))navigate(hash);});
render();
const recovering=new URLSearchParams(location.hash.slice(1)).get('type')==='recovery';
if(configured){api.verifyCallback().then(async user=>{if(user?.email_confirmed_at){await loadLive(user);if(recovering)modal('Neues Passwort',`<p>Wähle ein neues Passwort mit mindestens 12 Zeichen.</p><form id="password-form"><label>Neues Passwort<input name="password" type="password" autocomplete="new-password" minlength="12" required></label><div class="form-error" id="password-error" role="alert"></div><button type="submit" class="btn primary full">Passwort speichern</button></form>`);}else if(user){await api.logout();authModal();}else authModal();}).catch(error=>{toast(error.message);authModal();});}
if(location.hash.startsWith('#post/'))detail(location.hash.slice(6));
if('serviceWorker' in navigator && location.protocol!=='file:')navigator.serviceWorker.register(new URL('../sw.js',import.meta.url)).catch(()=>{});

async function syncLive(){if(isDemo()||state.overlay||document.hidden||state.loading)return;try{const [posts,userState,memberships]=await Promise.all([api.posts(),api.state(state.user.id),api.memberships()]);if(state.overlay||isDemo())return;state.posts=posts.map(p=>({...p,price:Number(p.price||0),likes:Number(p.likes||0),join_count:memberships.filter(m=>m.post_id===p.id).length}));Object.assign(state,userState);const input=document.activeElement;if(input?.tagName==='INPUT')return;render();}catch{}}
setInterval(syncLive,30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)syncLive();});
